import React, { useEffect, useState } from "react";
import { 
  Card, 
  Typography, 
  Button, 
  Table, 
  Tag, 
  Space, 
  Modal, 
  Form, 
  Select, 
  Switch, 
  Progress, 
  Alert,
  Descriptions,
  Tabs,
  Statistic,
  Row,
  Col,
  message
} from "antd";
import { 
  TrendingUpIcon, 
  BrainIcon, 
  ZapIcon, 
  NetworkIcon, 
  SettingsIcon,
  PlayIcon,
  CheckCircleIcon,
  AlertTriangleIcon
} from "lucide-react";
import { getTelegramUser, apiRequest } from "../api";

const { Title, Text, Paragraph } = Typography;
const { TabPane } = Tabs;

interface OptimizationDomain {
  key: string;
  name: string;
  description: string;
}

interface OptimizationResult {
  id: string;
  domain: string;
  confidence_score: number;
  suggested_parameters: Record<string, any>;
  expected_impact: Record<string, any>;
  mathematical_reasoning: string;
  llm_reasoning: string;
  risk_assessment: Record<string, any>;
  implementation_priority: number;
  applied: boolean;
  applied_at?: string;
  created_at: string;
}

interface OptimizationMetrics {
  domain_stats: Array<{
    domain: string;
    total_optimizations: number;
    applied_optimizations: number;
    application_rate: number;
    avg_confidence: number;
  }>;
  trends: Array<{
    date: string;
    optimizations_count: number;
    avg_confidence: number;
  }>;
}

export default function SoulOptimization() {
  const [loading, setLoading] = useState(false);
  const [domains, setDomains] = useState<OptimizationDomain[]>([]);
  const [results, setResults] = useState<OptimizationResult[]>([]);
  const [metrics, setMetrics] = useState<OptimizationMetrics | null>(null);
  const [selectedDomain, setSelectedDomain] = useState<string>("");
  const [optimizationInProgress, setOptimizationInProgress] = useState<string>("");
  const [showApplyModal, setShowApplyModal] = useState(false);
  const [selectedResult, setSelectedResult] = useState<OptimizationResult | null>(null);


  const loadData = async () => {
    try {
      setLoading(true);
      
      // Загружаем домены оптимизации
      try {
        const domainsData = await apiRequest("/admin/soul/advanced-optimization/domains", "GET");
        setDomains(domainsData.domains || []);
      } catch (error) {
        console.error("Ошибка загрузки доменов:", error);
      }

      // Загружаем результаты оптимизации
      try {
        const resultsData = await apiRequest("/admin/soul/advanced-optimization/results?limit=50", "GET");
        setResults(resultsData.results || []);
      } catch (error) {
        console.error("Ошибка загрузки результатов:", error);
      }

      // Загружаем метрики
      try {
        const metricsData = await apiRequest("/admin/soul/advanced-optimization/metrics", "GET");
        setMetrics(metricsData);
      } catch (error) {
        console.error("Ошибка загрузки метрик:", error);
      }

    } catch (error) {
      console.error("Ошибка загрузки данных оптимизации:", error);
      message.error("Ошибка загрузки данных");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const runOptimization = async (domain: string, force: boolean = false) => {
    try {
      setOptimizationInProgress(domain);
      
      const result = await apiRequest("/admin/soul/advanced-optimization/optimize", "POST", {
        domain: domain,
        force_optimization: force
      });
      
      message.success(`Оптимизация домена ${domain} завершена`);
      await loadData(); // Перезагружаем данные

    } catch (error) {
      console.error("Ошибка запуска оптимизации:", error);
      message.error("Ошибка запуска оптимизации");
    } finally {
      setOptimizationInProgress("");
    }
  };

  const applyOptimization = async (resultId: string, partial: boolean = false) => {
    try {
      const response = await fetch("/api/admin/soul/advanced-optimization/apply", {
        method: "POST",
        headers: buildAuthHeaders(),
        body: JSON.stringify({
          result_id: resultId,
          apply_partial: partial
        })
      });

      if (response.ok) {
        const result = await response.json();
        message.success(`Применено параметров: ${result.total_parameters}`);
        setShowApplyModal(false);
        setSelectedResult(null);
        await loadData();
      } else {
        const error = await response.json();
        message.error(`Ошибка применения: ${error.detail}`);
      }

    } catch (error) {
      console.error("Ошибка применения оптимизации:", error);
      message.error("Ошибка применения оптимизации");
    }
  };

  const getDomainIcon = (domain: string) => {
    switch (domain) {
      case "sleep": return <ZapIcon size={16} />;
      case "quant_selection": return <BrainIcon size={16} />;
      case "weight_balancing": return <NetworkIcon size={16} />;
      default: return <SettingsIcon size={16} />;
    }
  };

  const getConfidenceColor = (confidence: number) => {
    if (confidence >= 0.8) return "green";
    if (confidence >= 0.6) return "orange";
    return "red";
  };

  const getPriorityColor = (priority: number) => {
    if (priority >= 8) return "red";
    if (priority >= 6) return "orange";
    return "blue";
  };

  const getRiskLevel = (risks: Record<string, any>) => {
    const highRisks = Object.values(risks).filter(risk => risk === "high").length;
    if (highRisks > 0) return { level: "high", color: "red" };
    
    const mediumRisks = Object.values(risks).filter(risk => risk === "medium").length;
    if (mediumRisks > 0) return { level: "medium", color: "orange" };
    
    return { level: "low", color: "green" };
  };

  const resultsColumns = [
    {
      title: "Домен",
      dataIndex: "domain",
      key: "domain",
      render: (domain: string) => (
        <Space>
          {getDomainIcon(domain)}
          <Text>{domain.replace("_", " ")}</Text>
        </Space>
      )
    },
    {
      title: "Уверенность",
      dataIndex: "confidence_score",
      key: "confidence_score",
      render: (confidence: number) => (
        <Tag color={getConfidenceColor(confidence)}>
          {(confidence * 100).toFixed(1)}%
        </Tag>
      )
    },
    {
      title: "Приоритет",
      dataIndex: "implementation_priority",
      key: "implementation_priority",
      render: (priority: number) => (
        <Tag color={getPriorityColor(priority)}>
          {priority}/10
        </Tag>
      )
    },
    {
      title: "Риски",
      dataIndex: "risk_assessment",
      key: "risk_assessment",
      render: (risks: Record<string, any>) => {
        const riskLevel = getRiskLevel(risks);
        return <Tag color={riskLevel.color}>{riskLevel.level}</Tag>;
      }
    },
    {
      title: "Статус",
      dataIndex: "applied",
      key: "applied",
      render: (applied: boolean) => (
        <Tag color={applied ? "green" : "default"}>
          {applied ? "Применено" : "Ожидает"}
        </Tag>
      )
    },
    {
      title: "Создано",
      dataIndex: "created_at",
      key: "created_at",
      render: (date: string) => new Date(date).toLocaleString()
    },
    {
      title: "Действия",
      key: "actions",
      render: (_: any, record: OptimizationResult) => (
        <Space>
          <Button 
            size="small" 
            onClick={() => {
              setSelectedResult(record);
              setShowApplyModal(true);
            }}
            disabled={record.applied}
          >
            Применить
          </Button>
        </Space>
      )
    }
  ];

  return (
    <div style={{ padding: 24 }}>
      <div style={{ marginBottom: 24 }}>
        <Title level={2}>
          <TrendingUpIcon style={{ marginRight: 8, verticalAlign: "middle" }} />
          Оптимизация Soul
        </Title>
        <Text type="secondary">Продвинутая система оптимизации параметров Soul с использованием LLM и математических алгоритмов</Text>
      </div>

      <Tabs defaultActiveKey="optimization">
        <TabPane tab="Запуск Оптимизации" key="optimization">
          <Row gutter={[16, 16]}>
            {domains.map(domain => (
              <Col xs={24} md={12} lg={8} key={domain.key}>
                <Card
                  title={
                    <Space>
                      {getDomainIcon(domain.key)}
                      {domain.name}
                    </Space>
                  }
                  actions={[
                    <Button
                      key="optimize"
                      type="primary"
                      icon={<PlayIcon size={16} />}
                      loading={optimizationInProgress === domain.key}
                      onClick={() => runOptimization(domain.key)}
                    >
                      Оптимизировать
                    </Button>,
                    <Button
                      key="force"
                      icon={<AlertTriangleIcon size={16} />}
                      loading={optimizationInProgress === domain.key}
                      onClick={() => runOptimization(domain.key, true)}
                    >
                      Принудительно
                    </Button>
                  ]}
                >
                  <Paragraph ellipsis={{ rows: 3 }}>
                    {domain.description}
                  </Paragraph>
                </Card>
              </Col>
            ))}
          </Row>
        </TabPane>

        <TabPane tab="Результаты" key="results">
          <Card>
            <Table
              columns={resultsColumns}
              dataSource={results}
              rowKey="id"
              loading={loading}
              pagination={{ pageSize: 10 }}
            />
          </Card>
        </TabPane>

        <TabPane tab="Метрики" key="metrics">
          {metrics && (
            <Row gutter={[16, 16]}>
              <Col span={24}>
                <Card title="Статистика по доменам">
                  <Row gutter={[16, 16]}>
                    {metrics.domain_stats.map(stat => (
                      <Col xs={24} md={12} lg={8} key={stat.domain}>
                        <Card size="small">
                          <Statistic
                            title={stat.domain.replace("_", " ")}
                            value={stat.total_optimizations}
                            suffix="оптимизаций"
                          />
                          <div style={{ marginTop: 8 }}>
                            <Text type="secondary">Применено: </Text>
                            <Text strong>{(stat.application_rate * 100).toFixed(1)}%</Text>
                          </div>
                          <Progress
                            percent={stat.application_rate * 100}
                            size="small"
                            showInfo={false}
                            style={{ marginTop: 4 }}
                          />
                          <div style={{ marginTop: 8 }}>
                            <Text type="secondary">Средняя уверенность: </Text>
                            <Text strong>{(stat.avg_confidence * 100).toFixed(1)}%</Text>
                          </div>
                        </Card>
                      </Col>
                    ))}
                  </Row>
                </Card>
              </Col>
            </Row>
          )}
        </TabPane>
      </Tabs>

      {/* Модальное окно применения оптимизации */}
      <Modal
        title="Применить Оптимизацию"
        open={showApplyModal}
        onCancel={() => {
          setShowApplyModal(false);
          setSelectedResult(null);
        }}
        footer={[
          <Button key="cancel" onClick={() => setShowApplyModal(false)}>
            Отмена
          </Button>,
          <Button
            key="partial"
            onClick={() => selectedResult && applyOptimization(selectedResult.id, true)}
          >
            Частично
          </Button>,
          <Button
            key="full"
            type="primary"
            onClick={() => selectedResult && applyOptimization(selectedResult.id, false)}
          >
            Полностью
          </Button>
        ]}
        width={800}
      >
        {selectedResult && (
          <div>
            <Alert
              message={`Уверенность: ${(selectedResult.confidence_score * 100).toFixed(1)}%`}
              type={selectedResult.confidence_score >= 0.7 ? "success" : "warning"}
              style={{ marginBottom: 16 }}
            />

            <Descriptions title="Детали оптимизации" bordered size="small">
              <Descriptions.Item label="Домен" span={3}>
                {selectedResult.domain.replace("_", " ")}
              </Descriptions.Item>
              <Descriptions.Item label="Приоритет" span={3}>
                <Tag color={getPriorityColor(selectedResult.implementation_priority)}>
                  {selectedResult.implementation_priority}/10
                </Tag>
              </Descriptions.Item>
            </Descriptions>

            <Card title="Предлагаемые параметры" size="small" style={{ marginTop: 16 }}>
              <pre style={{ fontSize: 12, maxHeight: 200, overflow: "auto" }}>
                {JSON.stringify(selectedResult.suggested_parameters, null, 2)}
              </pre>
            </Card>

            <Card title="Ожидаемое влияние" size="small" style={{ marginTop: 16 }}>
              <pre style={{ fontSize: 12, maxHeight: 200, overflow: "auto" }}>
                {JSON.stringify(selectedResult.expected_impact, null, 2)}
              </pre>
            </Card>

            <Card title="Обоснование LLM" size="small" style={{ marginTop: 16 }}>
              <Text>{selectedResult.llm_reasoning}</Text>
            </Card>
          </div>
        )}
      </Modal>
    </div>
  );
}
